package compiler.parser;

import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;

import static org.junit.jupiter.api.Assertions.*;

/**
 * 用真实 LSL 案例 OrderedString 覆盖：参数化 trait 头、assumes / includes /
 * generated by / implies、自定义中缀算子 {@code -|}。
 */
class OrderedStringParsingTest {

    private static final String SAMPLE = """
            OrderedString(E, Str): trait
              assumes TotalOrder(E)
              includes DerivedOrders(Str)
              introduces
                empty: → Str
                __ -| __: E, Str → Str
                __ ∉ __: Str, Str → Bool
              asserts
                Str generated by empty, -|
                e, e1: E, s, s1: Str
                empty ∉ (e -| s);
                s ∉ empty;
                (e -| s) ∉ (e1 -| s1) ==
                  e ≠ e1 ∧ e ∉ (e1 -| s1) ∧ s ∉ s1;
              implies TotalOrder(Str)
            """;

    @Test
    @DisplayName("参数化 trait 头与 assumes / includes")
    void headerAndSections() {
        ParseResult result = Parser.parse(SAMPLE);
        assertFalse(result.hasErrors(), () -> "语法错误: " + result.errors());

        Ast.Trait trait = result.trait();
        assertEquals("OrderedString", trait.name());
        assertEquals(java.util.List.of("E", "Str"), trait.parameters());
        assertEquals(4, trait.sections().size());

        assertInstanceOf(Ast.Assumes.class, trait.sections().get(0));
        Ast.Assumes assumes = (Ast.Assumes) trait.sections().get(0);
        assertEquals("TotalOrder(E)", assumes.assumptions().get(0).display());

        assertInstanceOf(Ast.Includes.class, trait.sections().get(1));
        Ast.Includes includes = (Ast.Includes) trait.sections().get(1);
        assertEquals("DerivedOrders(Str)", includes.traits().get(0).display());
    }

    @Test
    @DisplayName("implies 子句")
    void impliesClause() {
        Ast.Trait trait = Parser.parse(SAMPLE).trait();
        assertEquals(1, trait.implied().size());
        assertEquals("TotalOrder(Str)", trait.implied().get(0).display());
    }

    @Test
    @DisplayName("generated by 子句与自定义算子签名")
    void generatedByAndSignatures() {
        Ast.Trait trait = Parser.parse(SAMPLE).trait();
        Ast.Asserts asserts = (Ast.Asserts) trait.sections().get(3);

        assertEquals(2, asserts.generatedBy().size());
        assertEquals("empty", asserts.generatedBy().get(0).name());
        assertEquals("-|", asserts.generatedBy().get(1).name());

        Ast.Introduces intro = (Ast.Introduces) trait.sections().get(2);
        assertEquals("__ -| __", intro.signatures().get(1).name());
        assertEquals(java.util.List.of("E", "Str"), intro.signatures().get(1).argumentSorts());
        assertEquals("Str", intro.signatures().get(1).resultSort());
    }

    @Test
    @DisplayName("自定义中缀算子 -| 参与表达式解析")
    void customInfixOperator() {
        Ast.Trait trait = Parser.parse(SAMPLE).trait();
        Ast.Asserts asserts = (Ast.Asserts) trait.sections().get(3);
        assertEquals(3, asserts.equations().size());

        // (e -| s) ∉ (e1 -| s1)
        Ast.Equation consEq = asserts.equations().get(2);
        Ast.Infix notIn = (Ast.Infix) consEq.left();
        assertEquals("∉", notIn.operator());
        assertInstanceOf(Ast.Infix.class, notIn.left());
        assertEquals("-|", ((Ast.Infix) notIn.left()).operator());
    }

    @Test
    @DisplayName("变量声明按排序分组")
    void groupedVarDecls() {
        Ast.Trait trait = Parser.parse(SAMPLE).trait();
        Ast.Asserts asserts = (Ast.Asserts) trait.sections().get(3);
        assertEquals(2, asserts.variables().size());
        assertEquals(java.util.List.of("e", "e1"), asserts.variables().get(0).names());
        assertEquals("E", asserts.variables().get(0).sort());
        assertEquals(java.util.List.of("s", "s1"), asserts.variables().get(1).names());
        assertEquals("Str", asserts.variables().get(1).sort());
    }

    @Test
    @DisplayName("语法树能渲染参数、asserts 与 implies")
    void renderTree() {
        String tree = TreePrinter.render(Parser.parse(SAMPLE).trait());
        assertTrue(tree.contains("Trait OrderedString(E, Str)"));
        assertTrue(tree.contains("assumes TotalOrder(E)"));
        assertTrue(tree.contains("includes DerivedOrders(Str)"));
        assertTrue(tree.contains("generated by empty, -|"));
        assertTrue(tree.contains("implies TotalOrder(Str)"));
    }
}
